function framed(g, im, x, y, w, h, a, filt) { g.save(); g.globalAlpha = a; g.fillStyle = '#efe4c8'; g.beginPath(); g.roundRect(x - 12, y - 12, w + 24, h + 24, 14); g.fill(); g.restore(); photo(g, im, x, y, w, h, 1.0, a, filt); }
